import pandas as pd

def solve(data):
     orders = pd.DataFrame(data['orders'], columns=['product_id','qty'])
     products = pd.DataFrame(data['products'], columns=['product_id','name'])
     joined = orders.merge(products, on='product_id', how='left', sort=False)
     return joined['name'].fillna('Unknown').tolist()
